/* @aomi-labs/widget-lib - Default Theme (shadcn compatible) */
/* Import via: @import "@aomi-labs/widget-lib/styles.css" (alias) */
/* Or directly: @import "@aomi-labs/widget-lib/themes/default.css" */

/* ============================================
   Theme Configuration (Tailwind v4 compatible)
   ============================================ */

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --text-xs: 0.75rem;
  --text-xs--line-height: calc(1 / 0.75);
  --text-sm: 0.875rem;
  --text-sm--line-height: calc(1.25 / 0.875);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 14px);
  --radius-4xl: calc(var(--radius) + 20px);

  @keyframes shimmer-sweep {
    from {
      background-position: 150% 0;
    }
    to {
      background-position: -100% 0;
    }
  }
  --animate-shimmer: shimmer-sweep var(--shimmer-duration, 1000ms) linear
    infinite both;

  /* Aomi design-system utilities (bg-aomi-surface, text-aomi-muted, …). */
  --color-aomi-bg: var(--aomi-bg);
  --color-aomi-surface: var(--aomi-surface);
  --color-aomi-surface-2: var(--aomi-surface-2);
  --color-aomi-raised: var(--aomi-raised);
  --color-aomi-border: var(--aomi-border);
  --color-aomi-fg: var(--aomi-fg);
  --color-aomi-muted: var(--aomi-muted);
  --color-aomi-accent: var(--aomi-accent);
  --color-aomi-accent-strong: var(--aomi-accent-strong);
  --color-aomi-accent-subtle: var(--aomi-accent-subtle);
  --color-aomi-on-accent: var(--aomi-on-accent);
  --color-aomi-hover: var(--aomi-hover);
  --color-aomi-pink: var(--aomi-pink);
  --color-aomi-success: var(--aomi-success);
  --color-aomi-warning: var(--aomi-warning);
  --color-aomi-danger: var(--aomi-danger);
  --color-aomi-danger-strong: var(--aomi-danger-strong);
  --color-aomi-on-danger: var(--aomi-on-danger);
  --color-aomi-info: var(--aomi-info);
  --color-aomi-ring: var(--aomi-ring);
  --color-aomi-accent-tint: var(--aomi-accent-tint);
  --color-aomi-accent-outline: var(--aomi-accent-outline);
  --color-aomi-overlay-border: var(--aomi-overlay-border);
}

/* ============================================
   Light Theme (Default)
   ============================================ */

/* `.light` is listed alongside `:root` so the light palette can also be scoped
   to a subtree — the mirror of `.dark`. Without it, dark is a one-way door:
   once `.dark` is on <html> nothing underneath can opt back out, which blocks
   embedding a light widget in a dark host page (and side-by-side previews). */
:root,
.light {
  --font-geist-sans:
    "Geist", "Inter", "SF Pro Display", "Segoe UI", system-ui, -apple-system,
    BlinkMacSystemFont, sans-serif;
  --font-geist-mono:
    "Geist Mono", "JetBrains Mono", "IBM Plex Mono", "SFMono-Regular", Menlo,
    Monaco, Consolas, "Liberation Mono", monospace;
  --aomi-font-wordmark:
    var(--font-source-serif-4, "Source Serif 4"), ui-serif, Georgia, Cambria,
    serif;
  --radius: 0.625rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.141 0.005 285.823);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.141 0.005 285.823);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.141 0.005 285.823);
  --primary: oklch(0.21 0.006 285.885);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.967 0.001 286.375);
  --secondary-foreground: oklch(0.21 0.006 285.885);
  --muted: oklch(0.967 0.001 286.375);
  --muted-foreground: oklch(0.552 0.016 285.938);
  --accent: oklch(0.967 0.001 286.375);
  --accent-foreground: oklch(0.21 0.006 285.885);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.92 0.004 286.32);
  --input: oklch(0.92 0.004 286.32);
  --ring: oklch(0.705 0.015 286.067);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.141 0.005 285.823);
  --sidebar-primary: oklch(0.21 0.006 285.885);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.967 0.001 286.375);
  --sidebar-accent-foreground: oklch(0.21 0.006 285.885);
  --sidebar-border: oklch(0.92 0.004 286.32);
  --sidebar-ring: oklch(0.705 0.015 286.067);

  /* ------------------------------------------------------------------------
     Aomi design-system tokens (source of truth: aomi-design tokens.css).
     One complete semantic set under the `aomi-*` namespace — redesigned
     surfaces are built ONLY from these, never mixed with the shadcn theme
     vocabulary. Cool, flat, editorial: ink text, sky interactive accent,
     pink decorative pop, no shadows. Light-first; `.dark` overrides below.
     ---------------------------------------------------------------------- */

  /* surfaces — cool (zinc) ramp */
  --aomi-bg: #ffffff; /* cool-0 */
  --aomi-surface: #fafafa; /* cool-50 */
  --aomi-surface-2: #f4f4f5; /* cool-100 */
  --aomi-raised: #ffffff; /* floating panels: menus, tooltips */
  --aomi-border: #e4e4e7; /* cool-200 */

  /* text */
  --aomi-fg: #09090b; /* cool-950 — "ink" */
  --aomi-muted: #71717a; /* cool-500 */

  /* accent — sky, THE interactive accent */
  --aomi-accent: #5288c2; /* sky-500 */
  --aomi-accent-strong: #416cac; /* deep sky · active */
  --aomi-accent-subtle: #e2eef8; /* sky-100 · selected fills */
  --aomi-on-accent: #ffffff;

  /* state + decorative + status */
  --aomi-hover: #e9e9ec; /* cool-150 · hover fill — still quiet on menus and
                            list rows, but a step below surface-2 (#f4f4f5).
                            At cool-100 it *was* surface-2, so anything already
                            filled with surface-2 — the round close button, the
                            chips — had no hover feedback at all. */
  --aomi-pink: #df5d90; /* pink-500 · decorative meters/pops */
  --aomi-success: #1f8558; /* darkened from #2e9e6b: it renders as text ("free"
                              rows, status labels), where the lighter green was
                              3.38:1 on white — under AA. Dark keeps the
                              brighter value below. */
  --aomi-warning: #d9982b;
  /* Focus: one ring for the whole system, so no surface falls back to the
     browser's default outline. */
  --aomi-ring: var(--aomi-accent);

  /* Alpha tints — the accent/10 + accent/45 pair and the overlay hairline
     recurred across chips, tinted buttons and menus as ad-hoc opacities. */
  --aomi-accent-tint: color-mix(in srgb, var(--aomi-accent) 10%, transparent);
  --aomi-accent-outline: color-mix(in srgb, var(--aomi-accent) 45%, transparent);
  --aomi-overlay-border: color-mix(in srgb, var(--aomi-muted) 30%, transparent);

  --aomi-danger: #d2495b; /* text + outline */
  --aomi-danger-strong: #b8394a; /* fills — white on #d2495b is only 4.3:1 */
  --aomi-on-danger: #ffffff;
  --aomi-info: #416cac;
}

/* ============================================
   Dark Theme
   ============================================ */

.dark {
  --background: oklch(0.141 0.005 285.823);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.21 0.006 285.885);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.21 0.006 285.885);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.92 0.004 286.32);
  --primary-foreground: oklch(0.21 0.006 285.885);
  --secondary: oklch(0.274 0.006 286.033);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.274 0.006 286.033);
  --muted-foreground: oklch(0.705 0.015 286.067);
  --accent: oklch(0.274 0.006 286.033);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(0.6 0 0 / 15%);
  --ring: oklch(0.552 0.016 285.938);
  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: oklch(0.21 0.006 285.885);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.488 0.243 264.376);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.274 0.006 286.033);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: oklch(0.552 0.016 285.938);

  /* Aomi design-system tokens — dark overrides. */
  /* Six distinct steps. The previous ramp collapsed surface-2, raised and
     border onto a single #27272a, which made every hairline on a panel a
     zero-contrast no-op: modal dividers, table rules, the meter track and the
     round close button all vanished. Each step below clears the one under it,
     and `border` clears all of them — on dark it carries the structure that
     fills carry on light. */
  --aomi-bg: #09090b; /* cool-950 */
  --aomi-surface: #18181b; /* cool-900 · recessed, mirrors light's #fafafa */
  --aomi-raised: #202024; /* panels lift off bg, and leave room for fills */
  --aomi-surface-2: #2e2e33; /* fills that sit ON a panel */
  --aomi-border: #3f3f46; /* hairline · reads on bg…surface-2 alike */

  --aomi-fg: #fafafa;
  --aomi-muted: #a1a1aa; /* cool-400 */

  --aomi-accent: #7facd6; /* sky-400 on dark */
  --aomi-accent-strong: #5288c2;
  --aomi-accent-subtle: #28354a; /* sky tint · must read as a selected row */
  --aomi-on-accent: #09090b;

  --aomi-hover: #4a4a52; /* one step above border, so a hover fill never
                            swallows the hairline of the row it lands on */
  --aomi-pink: #e77ba6; /* pink-400 — lifted for dark */
  --aomi-success: #35b37b; /* lifted: light's darkened green is for white
                              grounds and drops under AA on the dark panel */
  --aomi-danger: #e2687a; /* lifted so it carries on the dark ground */
  --aomi-danger-strong: #c34255;

  /* Derived tokens must be re-declared, not inherited. A `var()` inside a
     custom property substitutes against the element the property is *declared*
     on — so the `:root` definitions above bake in the light `--aomi-accent` /
     `--aomi-muted` and keep them even here. That happens to look right when
     `.dark` lands on `<html>` (both rules match the same element), but it
     silently breaks the moment `.dark` is applied to a subtree — a dark
     container around an embedded widget, or a side-by-side theme preview.
     Repeating them re-derives against the dark palette in either case. */
  --aomi-ring: var(--aomi-accent);
  --aomi-accent-tint: color-mix(in srgb, var(--aomi-accent) 10%, transparent);
  --aomi-accent-outline: color-mix(in srgb, var(--aomi-accent) 45%, transparent);
  --aomi-overlay-border: color-mix(in srgb, var(--aomi-muted) 30%, transparent);
}

/* ============================================
   Base Styles
   ============================================ */

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  /* One focus ring for every interactive element. Wrapped in :where() so it
     contributes no specificity — any component that wants its own focus
     treatment still wins, but nothing falls through to the browser default. */
  :where(a, button, input, select, textarea, summary, [role="switch"], [tabindex]:not([tabindex="-1"])):focus-visible {
    outline: 2px solid var(--aomi-ring);
    outline-offset: 2px;
  }

  :root {
    color-scheme: light;
  }

  :root.dark {
    color-scheme: dark;
  }

  body {
    @apply bg-background text-foreground;
  }
}

/* ============================================
   Mobile / iOS Safari fixes
   ============================================ */

/* Hide scrollbar on inline control bar (mobile swipe) */
.aui-composer-action-scroll::-webkit-scrollbar {
  display: none;
}

.aui-composer-action-scroll {
  scrollbar-width: none;
}

/* Thread viewport scrollbars stay scoped to the widget and disappear until useful.
   We rely on ::-webkit-scrollbar (Chrome/Safari) for a transparent, channel-less
   track and reserve `scrollbar-color` for Firefox only — in Chrome, setting
   `scrollbar-color` switches on the native themed track (the ugly channel) and
   overrides the custom track below. */
@supports (-moz-appearance: none) {
  .aui-thread-viewport {
    scrollbar-width: thin;
    scrollbar-color: transparent transparent;
  }

  .aui-thread-viewport:hover,
  .aui-thread-viewport:focus-within {
    scrollbar-color: hsl(var(--muted-foreground) / 0.22) transparent;
  }
}

.aui-thread-viewport::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.aui-thread-viewport::-webkit-scrollbar-track {
  background: transparent;
}

.aui-thread-viewport::-webkit-scrollbar-thumb {
  background: transparent;
  border: 2px solid transparent;
  border-radius: 9999px;
  background-clip: padding-box;
}

.aui-thread-viewport:hover::-webkit-scrollbar-thumb,
.aui-thread-viewport:focus-within::-webkit-scrollbar-thumb {
  background-color: hsl(var(--muted-foreground) / 0.22);
}

.aui-thread-viewport::-webkit-scrollbar-thumb:hover {
  background-color: hsl(var(--muted-foreground) / 0.38);
}

/* Thin, subtle scrollbar for command list dropdowns */
.aui-command-list {
  scrollbar-width: thin;
  scrollbar-color: hsl(var(--border) / 0.5) transparent;
}

.aui-command-list::-webkit-scrollbar {
  width: 4px;
}

.aui-command-list::-webkit-scrollbar-track {
  background: transparent;
}

.aui-command-list::-webkit-scrollbar-thumb {
  background: hsl(var(--border) / 0.5);
  border-radius: 9999px;
}

.aui-command-list::-webkit-scrollbar-thumb:hover {
  background: hsl(var(--border));
}

/* Match Aomi's editorial page titles. Hosts that load PT Serif through
   next/font provide --font-pt-serif; other consumers can use the named face. */
.aui-thread-welcome-title {
  font-family: var(--font-pt-serif, "PT Serif", ui-serif, Georgia, serif);
}

/* Prevent iOS from zooming on input focus (font-size >= 16px) */
@media screen and (max-width: 767px) {
  .aui-composer-input {
    font-size: 16px;
  }
}

/* Optional two-lane suggestion marquee. Consumers opt in by applying
   `aui-suggestions-marquee` to the AomiFrame root. */
.aui-suggestions-marquee .aui-thread-welcome-suggestions {
  order: 1;
  display: flex;
  width: 88%;
  margin-right: auto;
  margin-left: auto;
  flex-direction: column;
  gap: 0.875rem;
  overflow: hidden;
  padding-bottom: 0;
  mask-image: linear-gradient(
    to right,
    transparent,
    black 10%,
    black 90%,
    transparent
  );
  -webkit-mask-image: linear-gradient(
    to right,
    transparent,
    black 10%,
    black 90%,
    transparent
  );
}

.aui-suggestions-marquee .aui-thread-welcome-suggestions-track {
  display: flex;
  width: max-content;
  animation: aui-suggestion-marquee 30s linear infinite;
  will-change: transform;
}

.aui-suggestions-marquee
  .aui-thread-welcome-suggestions-track-secondary {
  display: flex;
  animation-duration: 72s;
  animation-delay: -17s;
}

.aui-suggestions-marquee .aui-thread-welcome-suggestions-group {
  width: max-content;
  flex-shrink: 0;
  flex-wrap: nowrap;
  justify-content: flex-start;
  gap: 1.25rem;
  padding-right: 1.25rem;
}

.aui-suggestions-marquee .aui-thread-welcome-suggestions-duplicate {
  display: flex;
}

.aui-suggestions-marquee .aui-thread-welcome-suggestion-display {
  display: block;
}

.aui-suggestions-marquee .aui-thread-welcome-suggestion {
  padding: 0.4375rem 0.75rem;
  font-size: 0.75rem;
}

.aui-suggestions-marquee .aui-thread-welcome-suggestion svg {
  width: 0.875rem;
  height: 0.875rem;
}

.aui-suggestions-marquee
  .aui-thread-welcome-root
  > div:has(> .aui-composer-root) {
  order: 2;
}

@media (prefers-reduced-motion: reduce) {
  .aui-suggestions-marquee .aui-thread-welcome-suggestions-track {
    width: 100%;
    animation: none;
  }

  .aui-suggestions-marquee
    .aui-thread-welcome-suggestions-track-secondary {
    display: flex;
  }

  .aui-suggestions-marquee .aui-thread-welcome-suggestions-group {
    width: 100%;
    flex-wrap: wrap;
    justify-content: center;
  }

  .aui-suggestions-marquee .aui-thread-welcome-suggestions-duplicate {
    display: none;
  }
}

@keyframes aui-suggestion-marquee {
  to {
    transform: translateX(-50%);
  }
}

/* ============================================
   Working trace (chain-of-thought)
   ============================================ */

@keyframes aui-working-sweep {
  from {
    background-position: 0% 0;
  }
  to {
    /* Shift by exactly one tile width so the tiled gradient loops with no
       visible seam or snap. background-size is 50%, so 100% of the
       positionable range equals one full tile. */
    background-position: 100% 0;
  }
}

/* Shimmering "Working" label — a soft highlight drifts across the text while
   the agent is still working. Uses the theme's own foreground/muted tokens so
   it inherits each app's palette (and dark mode) automatically.

   The gradient is a single soft bump (muted → foreground peak → muted) that is
   *tiled* twice across the text (background-size: 50%, repeat). Because the
   image repeats, a new highlight enters from the right exactly as the previous
   one leaves — there is never a fully-muted "dead" stretch, and the foreground
   peak is only ever a hairline so the text never goes solid. Translating by one
   whole tile per cycle makes the loop seamless (no snap on restart). */
.aui-working-shimmer {
  background-image: linear-gradient(
    100deg,
    var(--aomi-muted, var(--muted-foreground)) 0%,
    var(--aomi-muted, var(--muted-foreground)) 20%,
    var(--aomi-fg, var(--foreground)) 50%,
    var(--aomi-muted, var(--muted-foreground)) 80%,
    var(--aomi-muted, var(--muted-foreground)) 100%
  );
  background-size: 50% 100%;
  background-repeat: repeat;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: aui-working-sweep 2s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  .aui-working-shimmer {
    animation: none;
    color: var(--muted-foreground);
    -webkit-text-fill-color: var(--muted-foreground);
  }
}

/* The capped trace stays scrollable without exposing browser scrollbar chrome.
   Firefox uses the standard property, old Edge/IE use the MS override, and
   Chromium/Safari use the WebKit pseudo-element. Wheel, touch, and keyboard
   scrolling continue to work in each case. */
.aui-working-trace-scroll {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.aui-working-trace-scroll::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

/* Smoothly dissolve clipped rows into the theme background at both edges. These
   are color fades only — no backdrop blur, so text stays crisp until it fades.
   Multiple alpha stops avoid a visible cutoff while pointer-transparent overlays
   keep Chrome hover-wheel hit-testing on the viewport. */
.aui-working-trace-edge-fade-top {
  background: linear-gradient(
    to bottom,
    var(--aomi-bg, var(--background)) 0%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 92%, transparent) 14%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 76%, transparent) 32%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 54%, transparent) 52%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 31%, transparent) 70%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 13%, transparent) 86%,
    transparent 100%
  );
}

.aui-working-trace-edge-fade-bottom {
  background: linear-gradient(
    to top,
    var(--aomi-bg, var(--background)) 0%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 92%, transparent) 14%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 76%, transparent) 32%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 54%, transparent) 52%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 31%, transparent) 70%,
    color-mix(in oklch, var(--aomi-bg, var(--background)) 13%, transparent) 86%,
    transparent 100%
  );
}
